<?php
// Synthetic products and amounts only; no production database access.
require __DIR__.'/../vendor/autoload.php';
require __DIR__.'/../includes/report_input_templates.php';
require __DIR__.'/../includes/bod_kx_sell_in_input_store.php';
function kxCheck($ok,string $message): void {if(!$ok)throw new RuntimeException($message);}
function kxReject(callable $call,string $message): void {try{$call();}catch(InvalidArgumentException $e){return;}throw new RuntimeException($message);}
function kxProduct(\PhpOffice\PhpSpreadsheet\Worksheet\Worksheet $sheet,array $table,int $row,array $identity,array $values): void {
    foreach($identity as $field=>$value)$sheet->setCellValueExplicit([$table['identity'][$field],$row],(string)$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);
    foreach($values as $m=>$fields)foreach($fields as $field=>$value)$sheet->setCellValue([$table['months'][$m][$field],$row],$value);
}
function kxAggregate(array $rows,string $group,int $month): array {foreach($rows as $row)if($row['product']===$group&&$row['month']===$month)return $row;throw new RuntimeException('Expected subtotal missing');}

$book=buildReportInputTemplate('BOD KX Sell In','2026-10');
kxCheck($book->getSheetNames()===['PENJUALAN','ROD','_TEMPLATE'],'Two input sheets and hidden metadata');
$sales=$book->getSheetByName('PENJUALAN');$rod=$book->getSheetByName('ROD');$st=locateBodKxInputTables($sales,2026,false);$rt=locateBodKxInputTables($rod,2026,true);
kxCheck(count($st)===12&&count($rt)===7,'All supported sales and ROD groups included');
kxCheck(bodKxInputGroupCode('GB ET',true)==='ethical'&&bodKxInputGroupCode('GB1',true)==='gb1'&&bodKxInputGroupCode('KODC')==='kodc','Source Group Brand aliases remain supported');
foreach([$st,$rt] as $tables)foreach($tables as $table)kxCheck($table['last']-$table['first']+1===200,'Two hundred editable rows per group');
kxReject(fn()=>parseBodKxInputTemplate($book,'2026-10'),'Formula-generated zeros must not turn an empty template into data');
kxProduct($sales,$st['gb1'],$st['gb1']['first'],['barang'=>'Synthetic sales A'],[0=>['units'=>10,'rupiah'=>100],9=>['units'=>2,'rupiah'=>20],10=>['units'=>3,'rupiah'=>30]]);
kxProduct($sales,$st['gb1'],$st['gb1']['first']+1,['barang'=>'Synthetic sales B'],[0=>['units'=>0,'rupiah'=>0],9=>['units'=>-1,'rupiah'=>-10]]);
foreach(['ib_pharma','ib_food','solonat','kodc','toll_in','ethical','gb5'] as $group)kxProduct($sales,$st[$group],$st[$group]['first'],['barang'=>'Synthetic '.$group],[9=>['units'=>4,'rupiah'=>40]]);
kxProduct($rod,$rt['gb1'],$rt['gb1']['first'],['group'=>'GB1','code'=>'0001','name'=>'Synthetic target A','price'=>3],[0=>['units'=>5],9=>['units'=>10],10=>['units'=>0],11=>['units'=>20]]);
kxProduct($rod,$rt['gb1'],$rt['gb1']['first']+1,['code'=>'0002','name'=>'Synthetic target B','price'=>2],[9=>['units'=>2]]);
$qtyColumn=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($rt['gb1']['months'][9]['units']);$rpCell=$rod->getCell([$rt['gb1']['months'][9]['rupiah'],$rt['gb1']['first']]);
kxCheck($rpCell->getValue()==='='.$qtyColumn.$rt['gb1']['first'].'*E'.$rt['gb1']['first'],'Simple Unit times Harga Beli formula');
kxCheck((float)$rpCell->getCalculatedValue()===30.0,'Visible ROD formula calculates correctly');
// Stale/overwritten formula caches and edited display totals must never inflate imports.
$rpCell->setValue(999999);$sales->setCellValue([$st['gb1']['months'][9]['rupiah'],$st['gb1']['total']],999999);
$input=parseBodKxInputTemplate($book,'2026-10');kxCheck(count($input['sales'])===9&&count($input['rod'])===2,'Detail rows only; summaries not imported');
$merged=mergeBodKxInputState(bodKxInputEmptyState(2026),$input);$totals=bodKxInputAggregates($merged['state'],$merged['touches']);
$actual=kxAggregate($totals['sales'],'gb1',10);kxCheck($actual['units']==='1.000000'&&$actual['rupiah']==='10.000000','Monthly actual uses detail exactly once');
$target=kxAggregate($totals['rod'],'gb1',10);kxCheck($target['units']==='12.000000'&&$target['rupiah']==='34.000000','ROD totals derive Unit times Price, ignoring stale displayed values');
kxCheck(kxAggregate($totals['rod'],'gb1',11)['units']==='0.000000','Explicit zero remains zero');kxCheck($input['rod'][0]['units'][1]===null,'Blank month remains unavailable');
kxReject(fn()=>parseBodKxInputTemplate($book,'2025-10'),'Wrong-year upload rejected');
foreach(['Xlsx','Ods'] as $format){$path=tempnam('/tmp','kx-input-');try{$writer=\PhpOffice\PhpSpreadsheet\IOFactory::createWriter($book,$format);$writer->setPreCalculateFormulas(false);$writer->save($path);$loaded=\PhpOffice\PhpSpreadsheet\IOFactory::load($path);kxCheck(parseBodKxInputTemplate($loaded,'2026-10')===$input,'XLSX/ODS download and upload retains detail');$loaded->disconnectWorksheets();}finally{unlink($path);}}

$next=buildBodKxInputTemplate('2026-12',$merged['state']);kxCheck(parseBodKxInputTemplate($next,'2026-12')===$input,'Same-year history retains products, prices and all available months');foreach([['PENJUALAN','sales',false],['ROD','rod',true]] as [$name,$kind,$isRod])foreach(locateBodKxInputTables($next->getSheetByName($name),2026,$isRod) as $group=>$table){$expected=count(array_filter($input[$kind],static fn($r)=>$r['product']===$group));kxCheck($table['last']-$table['first']+1===$expected,'History download removes all unused product rows, retaining empty table headers and subtotals');}foreach(['Xlsx','Ods'] as $format){$path=tempnam('/tmp','kx-compact-');try{$writer=\PhpOffice\PhpSpreadsheet\IOFactory::createWriter($next,$format);$writer->setPreCalculateFormulas(false);$writer->save($path);$loaded=\PhpOffice\PhpSpreadsheet\IOFactory::load($path);kxCheck(parseBodKxInputTemplate($loaded,'2026-12')===$input,'Compact download with zero unused rows remains uploadable as XLSX/ODS');$loaded->disconnectWorksheets();}finally{unlink($path);}}
foreach([['PENJUALAN',false],['ROD',true]] as [$name,$isRod]){$sheet=$next->getSheetByName($name);$empty=locateBodKxInputTables($sheet,2026,$isRod)['gb2'];kxCheck($empty['last']<$empty['first'],'Unused table has no product rows');$sheet->insertNewRowBefore($empty['total'],1);$added=locateBodKxInputTables($sheet,2026,$isRod)['gb2'];kxProduct($sheet,$added,$added['first'],$isRod?['code'=>'0003','name'=>'Synthetic added later','price'=>7]:['barang'=>'Synthetic added later'],[9=>['units'=>1]]);}
$addedInput=parseBodKxInputTemplate($next,'2026-12');kxCheck(count($addedInput['sales'])===count($input['sales'])+1&&count($addedInput['rod'])===count($input['rod'])+1,'New products can be added back into tables after all blank rows were removed');
$next->disconnectWorksheets();
$earlier=buildBodKxInputTemplate('2026-10',$merged['state']);$earlierInput=parseBodKxInputTemplate($earlier,'2026-10');kxCheck($earlierInput['sales'][0]['units'][10]===null&&$earlierInput['rod'][0]['units'][11]===20.0,'Earlier downloads hide later actual months but retain all target months');
$again=mergeBodKxInputState($merged['state'],$earlierInput);kxCheck($again['state']===$merged['state'],'Reuploading earlier download preserves later saved actual months');$earlier->disconnectWorksheets();
$priceCorrection=$input;$priceCorrection['sales']=[];foreach($priceCorrection['rod'] as &$record)$record['units']=array_fill(0,12,null);unset($record);$priceCorrection['rod'][0]['price']=4;
$corrected=mergeBodKxInputState($merged['state'],$priceCorrection);$correctedTotals=bodKxInputAggregates($corrected['state'],$corrected['touches']);kxCheck(kxAggregate($correctedTotals['rod'],'gb1',10)['rupiah']==='44.000000'&&kxAggregate($correctedTotals['rod'],'gb1',12)['rupiah']==='80.000000','Price corrections update existing monthly amounts without losing units');
$partial=['year'=>2026,'sales'=>[['product'=>'gb1','barang'=>'Synthetic sales A','units'=>[0,0,null,null,null,null,null,null,null,null,null,null],'rupiah'=>array_fill(0,12,null)]],'rod'=>[]];
$partialMerged=mergeBodKxInputState($merged['state'],$partial);$partialTotals=bodKxInputAggregates($partialMerged['state'],$partialMerged['touches']);kxCheck(kxAggregate($partialTotals['sales'],'gb1',1)['units']==='0.000000'&&kxAggregate($partialTotals['sales'],'gb1',1)['rupiah']==='100.000000','Zero replaces units while absent rupiah input preserves previous rupiah');
foreach(['2025-10','2027-10','2026-01'] as $period){$blank=buildBodKxInputTemplate($period,$merged['state']);kxReject(fn()=>parseBodKxInputTemplate($blank,$period),'Other years and January start empty');foreach([['PENJUALAN',false],['ROD',true]] as [$name,$isRod])foreach(locateBodKxInputTables($blank->getSheetByName($name),(int)substr($period,0,4),$isRod) as $table){kxCheck($table['last']-$table['first']+1===200,'Fresh year/January retains exactly two hundred empty rows per group');for($row=$table['first'];$row<=$table['last'];$row++){kxCheck($blank->getSheetByName($name)->getCell([$table['identity'][$isRod?'name':'barang'],$row])->getValue()===null,'Fresh products have no names');foreach($table['months'] as $pair)kxCheck($blank->getSheetByName($name)->getCell([$pair['units'],$row])->getValue()===null,'Fresh monthly inputs are empty');}}$blank->disconnectWorksheets();}
foreach(['2025-10','2027-10'] as $period){$fresh=buildReportInputTemplate('BOD KX Sell In',$period);$y=(int)substr($period,0,4);$table=locateBodKxInputTables($fresh->getSheetByName('PENJUALAN'),$y,false)['gb1'];kxProduct($fresh->getSheetByName('PENJUALAN'),$table,$table['first'],['barang'=>'Synthetic future year'],[9=>['units'=>1,'rupiah'=>2]]);kxCheck(parseBodKxInputTemplate($fresh,$period)['year']===$y,'Year follows selected template period');$fresh->disconnectWorksheets();}

// Variable row counts and shifted columns are interpreted from labels.
foreach([[$sales,false],[$rod,true]] as [$sheet,$isRod]){$tables=locateBodKxInputTables($sheet,2026,$isRod);$sheet->insertNewRowBefore($tables['gb5']['last'],60);$tables=locateBodKxInputTables($sheet,2026,$isRod);$sheet->removeRow($tables['gb2']['first'],200);$sheet->insertNewRowBefore(1,3);$sheet->insertNewColumnBefore('B');}
$st=locateBodKxInputTables($sales,2026,false);$rt=locateBodKxInputTables($rod,2026,true);
for($i=0;$i<110;$i++){kxProduct($sales,$st['gb5'],$st['gb5']['first']+$i,['barang'=>'Synthetic large '.$i],[9=>['units'=>1,'rupiah'=>5]]);kxProduct($rod,$rt['gb5'],$rt['gb5']['first']+$i,['code'=>str_pad((string)$i,5,'0',STR_PAD_LEFT),'name'=>'Synthetic large '.$i,'price'=>5],[9=>['units'=>1]]);}
foreach($book->getAllSheets() as $sheet)foreach($sheet->getHyperlinkCollection() as $address=>$link)if($link->getUrl()==='')$sheet->setHyperlink($address,null);\PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($book)->clearCalculationCache();
$expanded=parseBodKxInputTemplate($book,'2026-10');$expandedMerge=mergeBodKxInputState(bodKxInputEmptyState(2026),$expanded);$expandedTotals=bodKxInputAggregates($expandedMerge['state'],$expandedMerge['touches']);kxCheck(kxAggregate($expandedTotals['sales'],'gb5',10)['units']==='110.000000'&&kxAggregate($expandedTotals['rod'],'gb5',10)['rupiah']==='550.000000','Added/deleted rows and shifted columns remain readable');
foreach(['Xlsx','Ods'] as $format){$path=tempnam('/tmp','kx-flex-');try{$writer=\PhpOffice\PhpSpreadsheet\IOFactory::createWriter($book,$format);$writer->setPreCalculateFormulas(false);$writer->save($path);$loaded=\PhpOffice\PhpSpreadsheet\IOFactory::load($path);kxCheck(parseBodKxInputTemplate($loaded,'2026-10')===$expanded,'Flexible XLSX/ODS upload preserves all details');$loaded->disconnectWorksheets();}finally{unlink($path);}}
$larger=buildBodKxInputTemplate('2026-11',$expandedMerge['state']);$table=locateBodKxInputTables($larger->getSheetByName('ROD'),2026,true)['gb5'];kxCheck($table['last']-$table['first']+1===110,'Next download includes every saved product without extra blank rows');$larger->disconnectWorksheets();
$duplicate=$st['gb1']['first']+2;kxProduct($sales,$st['gb1'],$duplicate,['barang'=>'Synthetic sales A'],[9=>['units'=>1]]);kxReject(fn()=>parseBodKxInputTemplate($book,'2026-10'),'Duplicate product rejected');$sales->setCellValue([$st['gb1']['identity']['barang'],$duplicate],'Synthetic distinct');$rod->setCellValue([$rt['gb1']['identity']['price'],$rt['gb1']['first']],-1);kxReject(fn()=>parseBodKxInputTemplate($book,'2026-10'),'Negative price rejected');$book->disconnectWorksheets();
echo "PASS combined BOD KX input: two detailed sheets, all groups/months, simple price formulas, totals without duplicate counting, signed/zero/blank, XLSX/ODS, flexible 110-product tables, history, January/year isolation and validation\n";
